function mergeState(
  parsed
) {
  const base =
    deepClone(
      DEFAULT_STATE
    );

  return {
    ...base,
    ...parsed,

    profile: {
      ...base.profile,
      ...(parsed.profile || {}),

      abilityByModule: {
        ...base
          .profile
          .abilityByModule,

        ...(
          (
            parsed.profile ||
            {}
          )
            .abilityByModule ||
          {}
        )
      },

      displayLevelByModule: {
        ...base
          .profile
          .displayLevelByModule,

        ...(
          (
            parsed.profile ||
            {}
          )
            .displayLevelByModule ||
          {}
        )
      },

      confidenceByModule: {
        ...base
          .profile
          .confidenceByModule,

        ...(
          (
            parsed.profile ||
            {}
          )
            .confidenceByModule ||
          {}
        )
      },

      effectiveAttemptsByModule: {
        ...base
          .profile
          .effectiveAttemptsByModule,

        ...(
          (
            parsed.profile ||
            {}
          )
            .effectiveAttemptsByModule ||
          {}
        )
      }
    },


    settings: {
      ...base.settings,
      ...(parsed.settings || {}),

      manualLevels: {
        ...base
          .settings
          .manualLevels,

        ...(
          (
            parsed.settings ||
            {}
          )
            .manualLevels ||
          {}
        )
      }
    },


    difficultyModel: {
      ...base
        .difficultyModel,

