}

functions.nextRequestId:
function nextRequestId(
  prefix = 'req'
) {
  requestCounter += 1;

  return `${prefix}-${Date.now().toString(36)}-${requestCounter.toString(36)}`;
}


/* 新的预取请求能不能顶掉旧的：
   题号更靠后的一定更新（用户已经往前走了）；
   题号相同时，后发出的那个更新（issued 单调递增）。
   反过来 —— 旧请求想覆盖新请求，一律拒绝。 */

functions.retryDelay:
function retryDelay(
  retryIndex = 0
) {
  return Math.round(
    RETRY_BASE_MS +
    Math.random() * RETRY_JITTER_MS
  );
}

functions.apiTimeoutError:
function apiTimeoutError(
  action,
  timeoutMs
) {
  const error = new Error(
    action === 'judge'
      ? `判题请求超时（${Math.round(timeoutMs / 1000)}s）`
      : `AI 请求超时（${Math.round(timeoutMs / 1000)}s）`
  );

  error.name = 'TimeoutError';
  error.code = 'CLIENT_TIMEOUT';
  error.timeoutMs = timeoutMs;
  error.httpStatus = null;

  return error;
}

functions.apiFailureKind:
function apiFailureKind(
  action,
  error
) {
  const judge =
    action === 'judge';

  if (error?.httpStatus) {
    return judge
      ? FAILURE_KINDS.JUDGE_HTTP
      : FAILURE_KINDS.GENERATE_HTTP;
  }

  if (
    error?.name === 'AbortError' ||
    error?.name === 'TimeoutError' ||
    error?.code === 'CLIENT_TIMEOUT'
  ) {
    return judge
      ? FAILURE_KINDS.JUDGE_TIMEOUT
      : FAILURE_KINDS.GENERATE_TIMEOUT;
  }

  if (error?.code === 'CLIENT_PROTOCOL_ERROR') {
    return judge
      ? FAILURE_KINDS.JUDGE_PROTOCOL
      : FAILURE_KINDS.GENERATE_PROTOCOL;
  }

  return judge
    ? FAILURE_KINDS.JUDGE_NETWORK
    : FAILURE_KINDS.GENERATE_NETWORK;
}


/* 400/401/403/404 这类错误重试多少次都是同一个结果，直接抛；
   429、5xx、超时、连接中断才值得再来一次。 */

functions.apiRetryable:
function apiRetryable(
  action,
  error
) {
  const status =
    Number(error?.httpStatus);

  if (
    Number.isFinite(status) &&
    error?.httpStatus !== null
  ) {
    return (
      status === 429 ||
      status === 408 ||
      status >= 500
    );
  }

  if (error?.code === 'CLIENT_PROTOCOL_ERROR') {
    return false;
  }

  const timedOut =
    error?.name === 'AbortError' ||
    error?.name === 'TimeoutError' ||
    error?.code === 'CLIENT_TIMEOUT';

  // 出题不重试超时：重试会把等待翻倍，而备用题库立刻就能兜住（见上）
  if (timedOut && action === 'generate') {
    return false;
  }

  return true;
}

functions.apiCall:
async function apiCall(
  action,
  payload = {},
  options = {}
) {
  const timeoutMs =
    Number(options.timeoutMs) ||
    API_TIMEOUTS[action] ||
    25000;

  const attempts =
    Math.max(
      1,
      Number(options.attempts) ||
      API_RETRY[action]?.attempts ||
      1
    );

  const requestId =
    payload.request_id ||
    nextRequestId(action);

  const attemptId =
    nextRequestId('attempt');

  const budgetMs =
    Number(options.budgetMs) ||
    API_BUDGETS[action] ||
    timeoutMs;

  const deadline =
    Date.now() + budgetMs;

  let lastError =
    null;

  for (
    let attempt = 0;
    attempt < attempts;
    attempt++
  ) {
    if (attempt > 0) {
      const delay =
        retryDelay(attempt - 1);

      if (Date.now() + delay + 1000 > deadline) {
        diagLog({
          level: 'error',
          action,
          event: 'retry_skipped',
          kind: apiFailureKind(action, lastError),
          message: '整体预算不足，不再重试',
          request_id: requestId,
          attempt_id: attemptId,
          attempt: attempt + 1,
          retry_index: attempt,
          duration_ms: Date.now() - (deadline - budgetMs),
          outcome: 'budget_exhausted'
        });

        break;
      }

      await sleep(
        delay
      );
    }

    const startedAt =
      Date.now();

    const remaining =
      deadline - startedAt;

    if (remaining <= 1000) {
      break;
    }

    /* 单次超时不超过剩余预算，否则「总预算」只是个装饰。
       下限 1 秒：低于它的超时会把正常的往返也掐掉，等于把「慢」误报成「断」。 */
    const attemptTimeout =
      Math.max(
        1000,
        Math.min(timeoutMs, remaining)
      );

    const controller =
      new AbortController();

    const timer =
      setTimeout(
        () => controller.abort(),
        attemptTimeout
      );

    try {
      const response =
        await fetch(
          AI_API_URL,
          {
            method: 'POST',
            signal: controller.signal,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action,
              request_id: requestId,
              session_id: payload.session_id ?? null,
              question_sequence: payload.question_sequence ?? null,
              attempt: attempt + 1,
              ...payload
            })
          }
        );

      const data =
        await response
          .json()
          .catch(
            () => null
          );

      if (!response.ok) {
        const error = new Error(
          data?.error ||
          `AI 请求失败 (${response.status})`
        );

        error.httpStatus =
          response.status;

        error.code =
          data?.code || null;

        throw error;
      }

      if (!data) {
        const error =
          new Error('AI 返回体不是 JSON');

        error.code = 'CLIENT_PROTOCOL_ERROR';
        error.httpStatus = null;

        throw error;
      }

      diagLog({
        level: 'info',
        action,
        event: 'http_attempt',
        message: `ok attempt ${attempt + 1}/${attempts}`,
        request_id: requestId,
        attempt_id: attemptId,
        session_id: payload.session_id ?? null,
        question_sequence: payload.question_sequence ?? null,
        attempt: attempt + 1,
        retry_index: attempt,
        duration_ms: Date.now() - startedAt,
        http_status: response.status,
        outcome: 'ok'
      });

      return data;

    } catch (caught) {
      const aborted =
        caught?.name === 'AbortError';

      const error =
        aborted
          ? apiTimeoutError(action, attemptTimeout)
          : caught;

      const retryable =
        apiRetryable(action, error);

      const willRetry =
        retryable &&
        attempt + 1 < attempts;

      diagLog({
        level: 'error',
        action,
        event: 'http_attempt',
        kind: apiFailureKind(action, error),
        message: error?.message || String(error),
        request_id: requestId,
        attempt_id: attemptId,
        session_id: payload.session_id ?? null,
        question_sequence: payload.question_sequence ?? null,
        attempt: attempt + 1,
        retry_index: attempt,
        duration_ms: Date.now() - startedAt,
        http_status: error?.httpStatus ?? null,
        outcome: willRetry ? 'retry' : 'failed'
      });

      lastError = error;

      if (!willRetry) {
        break;
      }

    } finally {
      clearTimeout(timer);
    }
  }

  throw lastError ||
    new Error('AI 请求失败');
}


/* ── 协议与版本（Task 5I）────────────────────────────────────

   旧的健康检查只做一件事：res.ok。于是不管线上跑的是哪一版引擎，
   界面都显示「DeepSeek 已连接」—— 而「连上了」和「连上了一个能按
   当前规则判题的版本」是两件完全不同的事。

   版本不匹配有两种后果，且都真实发生过：
     · 出题侧：服务端按旧规则标记 verification，客户端按新规则校验直接
       判它 stale，用户看到「AI 出题失败，已使用备用题」，但根本原因
       其实是劈叉部署，而不是模型不行；
     · 判题侧：旧服务端可能对某些形态给出「确定等价」的结论，而新客户端
       的引擎根本没法独立复核它 —— 这就是「错答放行」的入口。

   所以：
     1. 启动时读 health，比对五个版本，结论挂在界面上（不再只说「已连接」）；
     2. 每一次请求的响应里都带 versions，**逐次**校验。启动时对得上、返回时
        对不上（灰度、多实例、CDN 缓存）也必须拦。
   ========================================================= */
